# Private D52 augmented observation-correction backend tests
# (selection_est_method = "dr" with est_method = "dr").
# Real sealed owners (panel, frame, reader, link views) are built from the frozen
# independent finite reference (tests/testthat/fixtures/augmented_finite_v1, nine
# fixtures on 36 original F identities). Every expected value comes from the
# accepted reference tables; no expectation is generated by the backend.
#
# Tolerances are fixed before any installed run: points, nuisance roots,
# predictions and cell moments 1e-11 (the public point criterion); complete IF
# rows, component splits and covariances 1e-10. The reference analytic rows
# agree with complex-step refits to 4e-14 and all roots are machine-precision
# regular roots, while every scoped omission in the reference is >= 5e-5.

aug_ns <- function(name) {
  ns <- asNamespace("cdid")
  stopifnot(isNamespace(ns), environmentIsLocked(ns), bindingIsLocked(name, ns))
  fn <- get(name, envir = ns, inherits = FALSE)
  stopifnot(is.function(fn), identical(environment(fn), ns))
  fn
}

aug_has_installed_cdid <- function() isNamespaceLoaded("cdid") || requireNamespace("cdid", quietly = TRUE)

aug_fx_dir <- testthat::test_path("fixtures", "augmented_finite_v1")
aug_loader <- new.env(parent = globalenv())
sys.source(file.path(aug_fx_dir, "load_fixture.R"), envir = aug_loader)
aug_specs <- aug_loader$aug_fixture_specs
aug_mx <- function(x) max(c(0, abs(x)))
aug_tol_point <- 1e-11
aug_tol_if <- 1e-10

aug_load <- function(fixture_id, order = NULL, max_chunk_rows = 13L) {
  aug_loader$load_augmented_finite_reference(aug_fx_dir, fixture_id, order = order,
    max_chunk_rows = max_chunk_rows)
}

aug_fit <- function(fx, pair_outcomes = fx$pair_outcomes, X_frame = fx$X_frame,
                    selection_model = fx$spec$selection_model,
                    selection_pooling = fx$spec$selection_pooling,
                    imputation_pooling = fx$spec$imputation_pooling,
                    est_method = "dr", reader = fx$reader,
                    treatment_columns = fx$treatment_columns,
                    outcome_recipe = fx$outcome_recipe) {
  aug_ns("fit_augmented_backend")(
    reader = reader,
    link_views = fx$views,
    control = fx$control,
    glm_control = fx$glm_control,
    rank_tol = fx$rank_tol,
    outcome_recipe = outcome_recipe,
    treatment_columns = treatment_columns,
    est_method = est_method,
    imputation_pooling = imputation_pooling,
    selection_model = selection_model,
    selection_pooling = selection_pooling,
    X_frame = X_frame,
    pair_outcomes = pair_outcomes
  )
}

# Replay all rows; in details mode also collect every channel and nuisance row.
aug_collect <- function(fit, chunk_rows = 11L, link_batch_size = 2L, scale = "frame", details = TRUE) {
  st <- get("cp04_reader", fit$reader_ref, inherits = FALSE)$state
  N <- st$N
  L <- length(fit$links)
  out <- list(phi = matrix(NA_real_, N, L), link = vector("list", L), nuis = list(), batches = 0L)
  fields <- c("denplus", "numT", "T", "numBg", "Bg", "denminus", "numC", "C", "numBo", "Bo", "dr",
    "j_T_forward", "j_T_adjoint", "j_C_forward", "j_C_adjoint")
  for (l in seq_len(L)) {
    out$link[[l]] <- c(lapply(stats::setNames(fields, fields), function(f) rep(NA_real_, N)),
      list(components = matrix(NA_real_, N, 10L), reference_components = matrix(NA_real_, N, 4L)))
  }
  put <- function(name, rows, value) {
    if (is.null(out$nuis[[name]])) out$nuis[[name]] <<- matrix(NA_real_, N, ncol(value),
      dimnames = list(NULL, colnames(value)))
    out$nuis[[name]][rows, ] <<- value
  }
  out$info <- aug_ns("replay_augmented_if")(fit, chunk_rows = chunk_rows, link_batch_size = link_batch_size,
    callback = function(b) {
      stopifnot(identical(b$id, st$id[b$rows]))
      out$phi[b$rows, b$links] <<- b$phi
      out$batches <<- out$batches + 1L
      testthat::expect_lte(unname(aug_ns("cp04_payload")(b)["entries"]), b$diagnostics$output_entries_bound)
      if (!details) return(invisible(NULL))
      d <- b$details
      for (j in seq_along(b$links)) {
        ld <- d$links[[j]]
        l <- b$links[j]
        for (f in fields) out$link[[l]][[f]][b$rows] <<- ld[[f]]
        out$link[[l]]$components[b$rows, ] <<- ld$components
        colnames(out$link[[l]]$components) <<- colnames(ld$components)
        out$link[[l]]$reference_components[b$rows, ] <<- ld$reference_components
        colnames(out$link[[l]]$reference_components) <<- colnames(ld$reference_components)
      }
      put("a", b$rows, d$a)
      put("tau", b$rows, d$tau)
      put("eta", b$rows, d$eta)
      put("imputation_alpha", b$rows, d$imputation_alpha)
      for (gid in seq_along(d$imputation_beta)) put(paste0("imputation_beta.", gid), b$rows, d$imputation_beta[[gid]])
      th <- d$selection_theta
      colnames(th) <- as.character(d$selection_theta_ids)
      put("selection_theta", b$rows, th)
      put("or_theta", b$rows, d$or_if$theta)
      for (tid in seq_along(d$trt_if)) put(paste0("gamma.", tid), b$rows, d$trt_if[[tid]]$gamma)
      put("lambda", b$rows, matrix(d$lambda, ncol = 1L))
    },
    scale = scale, details = details)
  out
}

aug_cohort_index <- function(fit, k) match(if (k == 0) Inf else k, fit$cohorts)

aug_cell_id <- function(fit, k, pair) {
  pr <- aug_loader$aug_pairs[[pair]]
  s <- aug_loader$aug_dates[pr[1L]]
  t <- aug_loader$aug_dates[pr[2L]]
  kidx <- aug_cohort_index(fit, k)
  which(vapply(fit$cells, function(cf) cf$cohort_index == kidx && cf$pair$s == s && cf$pair$t == t, logical(1L)))
}

# Reference selection coordinate -> package theta coordinate (accepted
# up_map numbering) and its fitted value. The reference orders cells
# cohort-major (0, 2005, 2010) and indexes pair cells by e12/e23/e13 and date
# cells by 2000/2002/2005; the package orders by its own cohort index.
aug_selection_coordinate <- function(fit, fx, name) {
  sb <- fit$selection_backend
  um <- fit$up_map
  date <- identical(fx$spec$selection_model, "independent_period_logit")
  ref_k <- aug_loader$aug_reference_cohorts
  cell_of <- function(k, c) {
    kidx <- aug_cohort_index(fit, k)
    hit <- which(vapply(sb$cells, function(cl) {
      if (cl$cohort != kidx) return(FALSE)
      if (date) return(cl$t == aug_loader$aug_dates[c + 1L])
      pr <- aug_loader$aug_pairs[[c + 1L]]
      cl$pair$s == aug_loader$aug_dates[pr[1L]] && cl$pair$t == aug_loader$aug_dates[pr[2L]]
    }, logical(1L)))
    stopifnot(length(hit) == 1L)
    hit
  }
  gi <- as.integer(sub("^selection\\.group([0-9]+)\\..*$", "\\1", name))
  if (grepl("\\.alpha\\.", name)) {
    k <- as.numeric(sub("^.*\\.alpha\\.k([0-9]+)\\.cell[0-9]+$", "\\1", name))
    c <- as.integer(sub("^.*\\.cell([0-9]+)$", "\\1", name))
    cl <- sb$cells[[cell_of(k, c)]]
    list(id = um$alpha_coords[[cl$block_id]][cl$local_b], value = sb$blocks[[cl$block_id]]$alpha[cl$local_b])
  } else {
    m <- switch(fx$spec$selection_pooling,
      separate = sb$cells[[cell_of(ref_k[gi %/% 3L + 1L], gi %% 3L)]]$block_id,
      within_cohort = which(vapply(sb$block_specs, function(bs)
        identical(as.integer(bs$cohorts), as.integer(aug_cohort_index(fit, ref_k[gi + 1L]))), logical(1L))),
      across_cohorts = 1L)
    stopifnot(length(m) == 1L, length(um$beta_coords[[m]]) == 1L)
    list(id = um$beta_coords[[m]][1L], value = sb$blocks[[m]]$beta[1L])
  }
}

aug_imputation_coordinate <- function(fit, name) {
  gi <- as.integer(sub("^imputation\\.group([0-9]+)\\..*$", "\\1", name))
  if (grepl("\\.alpha\\.", name)) {
    k <- as.numeric(sub("^.*\\.alpha\\.k([0-9]+)\\.e[0-9]+$", "\\1", name))
    pair <- sub("^.*\\.(e[0-9]+)$", "\\1", name)
    cid <- aug_cell_id(fit, k, pair)
    stopifnot(length(cid) == 1L, fit$cells[[cid]]$group_id == gi + 1L)
    list(kind = "alpha", cid = cid, value = fit$cells[[cid]]$alpha)
  } else {
    col <- sub("^.*\\.beta\\.", "", name)
    list(kind = "beta", gid = gi + 1L, col = col, value = unname(fit$groups[[gi + 1L]]$beta[col]))
  }
}

aug_state <- new.env(parent = emptyenv())
aug_get <- function(fid) {
  key <- paste0("fit:", fid)
  if (is.null(aug_state[[key]])) {
    fx <- aug_load(fid, max_chunk_rows = 11L)
    fit <- aug_fit(fx)
    aug_state[[key]] <- list(fx = fx, fit = fit, col = aug_collect(fit, chunk_rows = 9L, link_batch_size = 2L))
  }
  aug_state[[key]]
}

testthat::test_that("packaged augmented reference pins and real sealed owners hold", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  testthat::expect_equal(aug_loader$aug_fixture_verify_hashes(aug_fx_dir), 16L)
  fx <- aug_load("pair_sep_jsep")
  testthat::expect_identical(fx$reader$state$N, 36L)
  testthat::expect_identical(fx$reader$state$n_A, 24L)
  testthat::expect_identical(fx$panel$n_a_units, 24L)
  testthat::expect_identical(fx$reader$state$universe, "F")
  # Off-A identities: singletons and zero-observers (all but one frame-only).
  testthat::expect_equal(sum(fx$A == 0), 12)
  testthat::expect_identical(colnames(fx$reader$state$Z), c("(Intercept)", "x2"))
  testthat::expect_identical(colnames(fx$X_frame), c("(Intercept)", "x1", "x2"))
})

testthat::test_that("all nine fixtures match points, nuisance roots, predictions and cell moments", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  n_points <- n_nuis <- n_pred <- 0L
  for (fid in aug_specs$fixture_id) {
    obj <- aug_get(fid)
    fx <- obj$fx
    fit <- obj$fit
    ex <- fx$expectations
    aug_ns("validate_augmented_backend")(fit)
    testthat::expect_s3_class(fit, "cdid_augmented_backend")
    testthat::expect_identical(c(fit$selection_est_method, fit$est_method), c("dr", "dr"))
    testthat::expect_identical(fit$selection_model, fx$spec$selection_model)
    testthat::expect_identical(fit$selection_pooling, fx$spec$selection_pooling)
    testthat::expect_identical(fit$imputation_pooling, fx$spec$imputation_pooling)
    testthat::expect_identical(fit$design_source, "X_frame")
    expected_groups <- switch(fx$spec$imputation_pooling, separate = 9L, within_cohort = 3L, across_cohorts = 1L)
    testthat::expect_length(fit$groups, expected_groups)
    expected_blocks <- switch(fx$spec$selection_pooling, separate = 9L, within_cohort = 3L, across_cohorts = 1L)
    testthat::expect_length(fit$selection_backend$blocks, expected_blocks)
    testthat::expect_length(fit$shared_or$blocks, 3L)
    testthat::expect_length(fit$treatments, 4L)
    testthat::expect_identical(fit$accounting$observation_logit_models, expected_blocks)

    # Link points and every ratio/normalizer (both normalizers retained).
    for (l in 1:4) {
      lf <- fit$links[[l]]
      got <- c(lf$mu, lf$T_gl, lf$C_ol, lf$B_gl, lf$B_ol, lf$d_plus, lf$d_minus,
        lf$num_T, lf$num_C, lf$num_Bg, lf$num_Bo)
      ref <- ex$value(paste0(c("dr", "T", "C", "Bg", "Bo", "denplus", "denminus", "numT", "numC", "numBg", "numBo"),
        ".l", l))
      testthat::expect_lt(aug_mx(got - ref), aug_tol_point)
      testthat::expect_equal(aug_ns("chained_full_link_estimate")(fit, l), lf$mu)
      n_points <- n_points + length(ref)
    }
    # Repeat rates and shares on F.
    lab <- aug_ns("imputation_cohort_label")(fit$cohorts)
    for (nm in c("a", "tau", "eta")) {
      testthat::expect_lt(aug_mx(fit[[nm]] - ex$value(paste0(nm, ".k", lab))), aug_tol_point)
    }
    testthat::expect_lt(abs(fit$lambda - ex$value("raw.lambda")), aug_tol_point)
    # Nuisance roots: imputation, observation probability, shared OR, treatment.
    for (nm in grep("^imputation\\.", ex$coordinates, value = TRUE)) {
      testthat::expect_lt(abs(aug_imputation_coordinate(fit, nm)$value - ex$value(nm)), aug_tol_point)
      n_nuis <- n_nuis + 1L
    }
    for (nm in grep("^selection\\.", ex$coordinates, value = TRUE)) {
      testthat::expect_lt(abs(aug_selection_coordinate(fit, fx, nm)$value - ex$value(nm)), aug_tol_point)
      n_nuis <- n_nuis + 1L
    }
    or_names <- grep("^OR\\.theta", ex$coordinates, value = TRUE)
    testthat::expect_identical(names(fit$shared_or$theta), or_names)
    testthat::expect_lt(aug_mx(fit$shared_or$theta - ex$value(or_names)), aug_tol_point)
    for (l in 1:4) {
      gam <- fit$treatments[[fit$links[[l]]$trt_id]]$coefficients
      testthat::expect_lt(aug_mx(gam - ex$value(paste0("treatment.l", l, ".gamma", seq_along(gam) - 1L))),
        aug_tol_point)
    }
    n_nuis <- n_nuis + length(or_names)

    # Actual-imputation, observation-probability and reconstructed predictions
    # on every needed cohort row (Delta read only on observed pairs).
    pr <- ex$predictions
    for (cid in seq_along(fit$cells)) {
      cf <- fit$cells[[cid]]
      gf <- fit$groups[[cf$group_id]]
      kval <- if (is.infinite(cf$cohort)) 0 else cf$cohort
      rows <- which(fx$reader$state$cohort_index == cf$cohort_index)
      jhat <- rep(cf$alpha, length(rows)) + if (gf$p > 0L) as.vector((cf$L * fx$X_frame[rows, gf$kept_columns, drop = FALSE]) %*% gf$beta) else 0
      q <- aug_ns("predict_pair_selection")(fit$selection_backend, rows, cf$q_id)$prob
      dy <- fx$Delta[[cf$pair_label]][rows]
      obs <- !is.na(dy)
      Z <- jhat
      Z[obs] <- jhat[obs] + (dy[obs] - jhat[obs]) / q[obs]
      ref <- pr[pr$cohort == kval & pr$pair == cf$pair_label, , drop = FALSE]
      ref <- ref[match(fx$ids[rows], ref$unit_id), , drop = FALSE]
      testthat::expect_false(anyNA(ref$unit_id))
      testthat::expect_identical(as.logical(ref$S), obs)
      testthat::expect_lt(aug_mx(jhat - ref$j), aug_tol_point)
      testthat::expect_lt(aug_mx(q - ref$q), aug_tol_point)
      testthat::expect_lt(aug_mx(cf$a_k / q - ref$v), aug_tol_point)
      testthat::expect_lt(aug_mx(Z - ref$Z), aug_tol_point)
      n_pred <- n_pred + 4L * length(rows)
      # Roster mass and augmented totals M_c(h), Y_c(h) for h = 1, x1, x2.
      key <- paste0(".k", kval, ".", cf$pair_label, ".h")
      testthat::expect_lt(abs(cf$M_one - ex$value(paste0("M", key, 0))), aug_tol_point)
      testthat::expect_lt(abs(cf$Yaug_one - ex$value(paste0("Y", key, 0))), aug_tol_point)
      for (h in 1:2) if (paste0("x", h) %in% names(cf$Yaug_z)) {
        testthat::expect_lt(abs(cf$M_z[[paste0("x", h)]] - ex$value(paste0("M", key, h))), aug_tol_point)
        testthat::expect_lt(abs(cf$Yaug_z[[paste0("x", h)]] - ex$value(paste0("Y", key, h))), aug_tol_point)
      }
      # The cohort mass identity M_c(1) = H_N[w I_k A] on F.
      testthat::expect_equal(cf$M_one, sum(fx$w[rows] * fx$A[rows]) / fx$N, tolerance = 1e-13)
    }
  }
  testthat::expect_gte(n_points, 9L * 44L)
  testthat::expect_gt(n_nuis, 9L * 10L)
  testthat::expect_gt(n_pred, 9L * 4L * 100L)
})

testthat::test_that("complete original-unit IF rows, channel splits and nuisance rows match all nine fixtures", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  off_A_mask_effect <- 0
  for (fid in aug_specs$fixture_id) {
    obj <- aug_get(fid)
    fx <- obj$fx
    fit <- obj$fit
    col <- obj$col
    ex <- fx$expectations
    N <- fx$N
    for (l in 1:4) {
      lk <- col$link[[l]]
      testthat::expect_lt(aug_mx(col$phi[, l] - ex$if_row(paste0("dr.l", l))), aug_tol_if)
      testthat::expect_lt(aug_mx(lk$dr - col$phi[, l]), 1e-14)
      for (f in c("T", "C", "Bg", "Bo", "denplus", "denminus", "numT", "numC", "numBg", "numBo")) {
        testthat::expect_lt(aug_mx(lk[[f]] - ex$if_row(paste0(f, ".l", l))), aug_tol_if)
      }
      # The independent j / q / rate / remaining split of the complete link IF.
      for (f in c("j_score_pullback", "q_score_pullback", "all_rate_paths",
                  "remaining_direct_and_downstream_scores")) {
        testthat::expect_lt(aug_mx(lk$reference_components[, f] - ex$component(l, f)), aug_tol_if)
      }
      testthat::expect_lt(aug_mx(rowSums(lk$components) - col$phi[, l]), 1e-13)
      # Adjoint pullback equals the forward imputation rows.
      testthat::expect_lt(aug_mx(lk$j_T_forward - lk$j_T_adjoint), 1e-12)
      testthat::expect_lt(aug_mx(lk$j_C_forward - lk$j_C_adjoint), 1e-12)
    }
    lab <- aug_ns("imputation_cohort_label")(fit$cohorts)
    for (nm in c("a", "tau", "eta")) for (k in lab) {
      testthat::expect_lt(aug_mx(col$nuis[[nm]][, paste0(nm, ".k", k)] - ex$if_row(paste0(nm, ".k", k))), aug_tol_if)
    }
    for (nm in grep("^selection\\.", ex$coordinates, value = TRUE)) {
      sc <- aug_selection_coordinate(fit, fx, nm)
      testthat::expect_lt(aug_mx(col$nuis$selection_theta[, as.character(sc$id)] - ex$if_row(nm)), aug_tol_if)
    }
    for (nm in grep("^imputation\\.", ex$coordinates, value = TRUE)) {
      ic <- aug_imputation_coordinate(fit, nm)
      got <- if (ic$kind == "alpha") col$nuis$imputation_alpha[, ic$cid] else
        col$nuis[[paste0("imputation_beta.", ic$gid)]][, ic$col]
      testthat::expect_lt(aug_mx(got - ex$if_row(nm)), aug_tol_if)
    }
    for (nm in grep("^OR\\.theta", ex$coordinates, value = TRUE)) {
      testthat::expect_lt(aug_mx(col$nuis$or_theta[, nm] - ex$if_row(nm)), aug_tol_if)
    }
    for (l in 1:4) {
      tid <- fit$links[[l]]$trt_id
      G <- col$nuis[[paste0("gamma.", tid)]]
      for (p in seq_len(ncol(G))) {
        testthat::expect_lt(aug_mx(G[, p] - ex$if_row(paste0("treatment.l", l, ".gamma", p - 1L))), aug_tol_if)
      }
    }
    # Every F identity carries a row; off-A rows are retained (not masked).
    testthat::expect_false(anyNA(col$phi))
    # The intercept-only fixture has a structural off-A cancellation. Compare
    # every off-A row to its unchanged oracle; the other fixtures detect masking.
    expected_off_A <- vapply(1:4, function(l) ex$if_row(paste0("dr.l", l))[fx$A == 0],
      numeric(sum(fx$A == 0)))
    testthat::expect_lt(aug_mx(col$phi[fx$A == 0, ] - expected_off_A), aug_tol_if)
    off_A_mask_effect <- max(off_A_mask_effect, aug_mx(expected_off_A))
  }
  testthat::expect_gt(off_A_mask_effect, 1e-6)
})

testthat::test_that("frame/core scaling, chunk and link-batch invariance, row order and the private hook agree", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  for (fid in c("date_sep_jwithin", "pair_V_across_jwithin")) {
    obj <- aug_get(fid)
    fit <- obj$fit
    fx <- obj$fx
    a <- aug_collect(fit, chunk_rows = 5L, link_batch_size = 1L, details = FALSE)
    b <- aug_collect(fit, chunk_rows = 11L, link_batch_size = 4L, details = FALSE)
    core <- aug_collect(fit, chunk_rows = 7L, link_batch_size = 3L, scale = "core", details = FALSE)
    testthat::expect_lt(aug_mx(a$phi - obj$col$phi), 1e-12)
    testthat::expect_lt(aug_mx(b$phi - obj$col$phi), 1e-12)
    testthat::expect_identical(a$info$normalization_count, 36L)
    testthat::expect_identical(core$info$normalization_count, 24L)
    testthat::expect_lt(aug_mx(core$phi - (24 / 36) * obj$col$phi), 1e-15)
    testthat::expect_true(a$info$all_F_identities)
    # Row order of the supplied roster: identical values mapped by identity.
    perm <- c(seq.int(36L, 2L, -2L), seq.int(35L, 1L, -2L))
    fx_p <- aug_load(fid, order = perm, max_chunk_rows = 7L)
    fit_p <- aug_fit(fx_p)
    col_p <- aug_collect(fit_p, chunk_rows = 7L, link_batch_size = 2L, details = FALSE)
    testthat::expect_lt(aug_mx(vapply(fit_p$links, `[[`, numeric(1L), "mu") -
      vapply(fit$links, `[[`, numeric(1L), "mu")), 1e-12)
    testthat::expect_lt(aug_mx(col_p$phi[match(fx$ids, fx_p$ids), ] - obj$col$phi), 1e-11)
    # The private exact-difference hook and the sealed panel read agree exactly
    # when the hook carries the panel's own level differences.
    fit_panel <- aug_fit(fx, pair_outcomes = NULL)
    fit_hook <- aug_fit(fx, pair_outcomes = fx$pair_outcomes_from_levels)
    testthat::expect_identical(vapply(fit_panel$links, `[[`, numeric(1L), "mu"),
      vapply(fit_hook$links, `[[`, numeric(1L), "mu"))
  }
})

testthat::test_that("joint unit/cluster covariance, identity projection and eta aggregate match the reference", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  D <- matrix(c(1, 0, 1, 1, 0, 1, 1, -1), 4L, 2L)
  loading <- solve(crossprod(D), t(D))
  for (fid in aug_specs$fixture_id) {
    obj <- aug_get(fid)
    fx <- obj$fx
    fit <- obj$fit
    ex <- fx$expectations
    N <- fx$N
    mu <- vapply(fit$links, `[[`, numeric(1L), "mu")
    phi <- obj$col$phi
    lab <- aug_ns("imputation_cohort_label")(fit$cohorts)
    eta <- stats::setNames(fit$eta, lab)
    xi_eta <- obj$col$nuis$eta
    xi_tau <- obj$col$nuis$tau
    # Fixed identity projection and smooth eta-share aggregate (reference algebra).
    theta <- as.vector(loading %*% mu)
    theta_if <- phi %*% t(loading)
    e2 <- eta[c("2005", "2010")]
    share <- e2 / sum(e2)
    x2 <- xi_eta[, paste0("eta.k", c("2005", "2010")), drop = FALSE]
    dshare <- (x2 * sum(e2) - outer(rowSums(x2), e2)) / sum(e2)^2
    agg <- sum(share * theta)
    agg_if <- as.vector(theta_if %*% share + dshare %*% theta)
    pv <- stats::setNames(ex$projection$value, ex$projection$coordinate)
    testthat::expect_lt(aug_mx(c(theta, agg) - pv[c("effect1", "effect2", "eta_aggregate")]), aug_tol_point)
    pif <- ex$projection_if
    for (j in 1:3) {
      nm <- c("effect1", "effect2", "eta_aggregate")[j]
      r <- pif[pif$coordinate == nm, , drop = FALSE]
      got <- if (j < 3L) theta_if[, j] else agg_if
      testthat::expect_lt(aug_mx(got - r$analytic[match(fx$ids, r$unit_id)]), aug_tol_if)
    }
    joint <- cbind(phi, xi_tau[, paste0("tau.k", c("0", "2005", "2010"))],
      xi_eta[, paste0("eta.k", c("0", "2005", "2010"))], theta_if, agg_if)
    colnames(joint) <- c(paste0("dr.l", 1:4), paste0("tau.k", c("0", "2005", "2010")),
      paste0("eta.k", c("0", "2005", "2010")), "identity_effect1", "identity_effect2", "eta_aggregate")
    cv <- ex$covariance
    for (regime in c("unit", "cluster")) {
      grp <- if (regime == "unit") fx$ids else fx$cluster
      S <- rowsum(joint, grp, reorder = FALSE)
      V <- crossprod(S) / N^2
      r <- cv[cv$regime == regime, , drop = FALSE]
      got <- V[cbind(match(r$coordinate1, colnames(V)), match(r$coordinate2, colnames(V)))]
      testthat::expect_false(anyNA(got))
      testthat::expect_lt(aug_mx(got - r$covariance), aug_tol_if)
    }
    # Core link rows (raw n_A/N scaling, divisor n_A) reproduce the frame link covariance.
    core <- aug_collect(fit, chunk_rows = 11L, link_batch_size = 4L, scale = "core", details = FALSE)
    for (grp in list(fx$ids, fx$cluster)) {
      Sf <- rowsum(phi, grp, reorder = FALSE)
      Sc <- rowsum(core$phi, grp, reorder = FALSE)
      n_A <- fx$reader$state$n_A
      testthat::expect_lt(aug_mx(crossprod(Sc) / n_A^2 - crossprod(Sf) / N^2), 1e-14)
    }
  }
})

testthat::test_that("exact finite identities: intercept cancellation, rate zeros, E5, centering and Euler", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  for (fid in aug_specs$fixture_id) {
    obj <- aug_get(fid)
    fit <- obj$fit
    col <- obj$col
    for (l in 1:4) {
      lf <- fit$links[[l]]
      lk <- col$link[[l]]
      # E4: the treated direct-rate loadings of T and B_g vanish identically, so
      # the link rate channel is the control part alone.
      testthat::expect_lt(abs(lf$a_coeff_T_g), 1e-12)
      testthat::expect_lt(abs(lf$a_coeff_Bg_g), 1e-12)
      control_rate <- as.vector(col$nuis$a[, lf$control_cohort_indices, drop = FALSE] %*%
        (lf$a_coeff_C_k - lf$a_coeff_Bo_k))
      testthat::expect_lt(aug_mx(lk$components[, "rate"] + control_rate), 1e-12)
      if (length(lf$control_cohort_indices) == 1L) {
        # Singleton K: the control direct-rate loading vanishes identically.
        testthat::expect_lt(abs(lf$a_coeff_C_k - lf$a_coeff_Bo_k), 1e-12)
        testthat::expect_lt(aug_mx(lk$components[, "rate"]), 1e-12)
      }
      # Degree zero: centered IF; degree one: raw rows average to their value.
      testthat::expect_lt(abs(mean(col$phi[, l])), 1e-12)
      for (f in c("T", "C", "Bg", "Bo")) testthat::expect_lt(abs(mean(lk[[f]])), 1e-12)
      testthat::expect_lt(abs(mean(lk$denplus) - lf$d_plus), 1e-12)
      testthat::expect_lt(abs(mean(lk$denminus) - lf$d_minus), 1e-12)
      testthat::expect_lt(abs(mean(lk$numT) - lf$num_T), 1e-12)
      testthat::expect_lt(abs(mean(lk$numC) - lf$num_C), 1e-12)
      # E3: the local OR intercept cancels; the link is (T - C) - (dbar+ - dbar-)' beta.
      testthat::expect_lt(abs(lf$mu - ((lf$T_gl - lf$C_ol) - sum(lf$d_bar_diff_or * fit$shared_or$beta))), 1e-12)
    }
  }
  # E3 with an intercept-only OR: the augmented link equals T - C for the same correction.
  io <- aug_get("pair_intercept_only")$fit
  testthat::expect_identical(io$shared_or$p, 0L)
  for (lf in io$links) testthat::expect_lt(abs(lf$mu - (lf$T_gl - lf$C_ol)), 1e-13)
  # E5: intercept-only q with local imputation intercepts: Y_c(1) = Y^I_c(1) for every cell.
  for (cf in io$cells) testthat::expect_lt(abs(cf$Yaug_one - cf$Y_one), 1e-13)
  # With covariate-dependent q the augmented totals differ from pure imputation.
  sep <- aug_get("pair_sep_jsep")$fit
  testthat::expect_gt(max(vapply(sep$cells, function(cf) abs(cf$Yaug_one - cf$Y_one), numeric(1L))), 1e-6)
})

testthat::test_that("the reference comparison detects omitted q, j, rate, normalizer and singleton-block paths", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  material <- list(j = 0, q = 0, rates = 0, or_q = 0, or_j = 0, treated_den = 0, control_den = 0, singleton = 0)
  for (fid in aug_specs$fixture_id) {
    obj <- aug_get(fid)
    fit <- obj$fit
    ex <- obj$fx$expectations
    for (l in 1:4) {
      lk <- obj$col$link[[l]]
      ref <- ex$if_row(paste0("dr.l", l))
      rc <- lk$reference_components
      cm <- lk$components
      # A complete IF passes; an IF missing a path would miss by the path's size.
      testthat::expect_lt(aug_mx(obj$col$phi[, l] - ref), aug_tol_if)
      material$j <- max(material$j, aug_mx(obj$col$phi[, l] - rc[, "j_score_pullback"] - ref))
      material$q <- max(material$q, aug_mx(obj$col$phi[, l] - rc[, "q_score_pullback"] - ref))
      material$rates <- max(material$rates, aug_mx(obj$col$phi[, l] - rc[, "all_rate_paths"] - ref))
      material$or_q <- max(material$or_q, aug_mx(cm[, "OR_selection"]))
      material$or_j <- max(material$or_j, aug_mx(cm[, "OR_imputation"]))
      # Freezing a ratio normalizer drops R * psi(den) / den.
      lf <- fit$links[[l]]
      material$treated_den <- max(material$treated_den, aug_mx(lf$T_gl * lk$denplus / lf$d_plus -
        lf$B_gl * lk$denplus / lf$d_plus))
      material$control_den <- max(material$control_den, aug_mx((lf$C_ol - lf$B_ol) * lk$denminus / lf$d_minus))
    }
    # Changed trap: the singleton-block M^Delta(d_tilde) intercept forcing is retained.
    b1 <- fit$shared_or$blocks[[1L]]
    if (length(b1$control_cell_ids) == 1L && fit$shared_or$p > 0L && fit$shared_or$intercept) {
      material$singleton <- max(material$singleton, aug_mx(b1$j_force_beta_alpha))
    }
  }
  for (nm in names(material)) testthat::expect_gt(material[[nm]], 1e-4)
})

testthat::test_that("retained aliases: outcome aliases reproduce the reference; aliased logit designs refuse", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  alias <- aug_get("pair_retained_alias")
  base <- aug_get("pair_sep_jsep")
  for (g in alias$fit$groups) {
    testthat::expect_identical(g$kept_columns, c("x1", "x2"))
    testthat::expect_setequal(g$basis$aliased_columns, c("x1_twice", "x1_plus_x2"))
  }
  testthat::expect_setequal(alias$fit$shared_or$basis$aliased_columns, c("x1_twice", "x1_plus_x2"))
  testthat::expect_lt(aug_mx(vapply(alias$fit$links, `[[`, numeric(1L), "mu") -
    vapply(base$fit$links, `[[`, numeric(1L), "mu")), 1e-12)
  testthat::expect_lt(aug_mx(alias$col$phi - base$col$phi), 1e-11)
  # The unchanged rank policies refuse aliased treatment and selection designs.
  fx <- alias$fx
  # Under these unchanged exact-alias inputs and 1e-15 IRLS controls, the
  # existing solver refuses with convergence or boundary error before a singular-information check.
  err_trt_alias <- testthat::expect_error(
    aug_fit(fx, treatment_columns = colnames(fx$X_frame)),
    class = "cdid_ipw_fit_error"
  )
  testthat::expect_true(
    inherits(err_trt_alias, "cdid_cp04_convergence_error") ||
      inherits(err_trt_alias, "cdid_cp04_boundary_error")
  )
  x2 <- fx$reader$state$Z[, "x2"]
  Q_alias <- cbind(`(Intercept)` = 1, x2 = x2, x2_twice = 2 * x2, x2_shift = 3 + x2)
  reader_alias <- aug_ns("construct_cp04_frame_reader")(fx$frame, fx$ids, Q_alias, fx$g, fx$w, fx$control,
    has_intercept = TRUE)
  err_sel_alias <- testthat::expect_error(
    aug_fit(fx, reader = reader_alias),
    class = "cdid_ipw_fit_error"
  )
  testthat::expect_true(
    inherits(err_sel_alias, "cdid_cp04_rank_error") ||
      inherits(err_sel_alias, "cdid_cp04_boundary_error")
  )
})

testthat::test_that("legitimate refusals: no outcome design from the selection reader, method, universe, hook", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- aug_load("pair_sep_jsep")
  # reader$state$Z is the observation-probability design and never the outcome design.
  e <- testthat::expect_error(aug_fit(fx, X_frame = NULL), class = "cdid_augmented_identity_error")
  testthat::expect_match(conditionMessage(e), "reader$state$Z", fixed = TRUE)
  for (m in c("ipw", "reg")) testthat::expect_error(aug_fit(fx, est_method = m), class = "cdid_augmented_method_error")
  testthat::expect_error(aug_fit(fx, selection_model = "probit"), class = "cdid_cp04_unsupported_error")
  testthat::expect_error(aug_fit(fx, imputation_pooling = "pooled"), class = "cdid_imputation_pooling_error")
  # A non-F fitting roster is refused (U = A with an explicit justification).
  A_rows <- fx$reader$state$a_index > 0L
  reader_A <- aug_ns("construct_cp04_frame_reader")(fx$frame, fx$ids, fx$reader$state$Z, fx$g, fx$w, fx$control,
    U = A_rows, universe = "A", justification = "declared representative repeat observers", has_intercept = TRUE)
  testthat::expect_error(aug_fit(fx, reader = reader_A), class = "cdid_augmented_universe_error")
  # The private exact-difference hook must match the sealed observation mask.
  bad <- fx$pair_outcomes
  bad[[1L]][which(is.na(bad[[1L]]))[1L]] <- 0
  testthat::expect_error(aug_fit(fx, pair_outcomes = bad), class = "cdid_augmented_support_error")
})

testthat::test_that("retained payload, IF envelopes and the absence of dense N x cells arrays", {
  testthat::skip_if_not(aug_has_installed_cdid(), "Installed cdid namespace required.")
  for (fid in c("pair_across_jacross", "date_within_jacross", "pair_V_across_jwithin")) {
    obj <- aug_get(fid)
    fit <- obj$fit
    N <- obj$fx$N
    acc <- fit$accounting
    testthat::expect_lte(acc$owned_entries + acc$borrowed_entries, acc$retained_bound)
    testthat::expect_equal(acc$owned_entries, unname(aug_ns("cp04_payload")(fit)["entries"]))
    testthat::expect_false(acc$full_F_by_link_IF_retained)
    testthat::expect_equal(acc$augmentation_passes, 3L)
    testthat::expect_gte(acc$work_ops_bound, acc$selection_work_ops_bound)
    # No retained matrix has one row per F identity (no N x cells/pairs/links array).
    wide <- 0L
    scan <- function(x) {
      if (is.environment(x)) return(invisible(NULL))
      if (is.matrix(x) && nrow(x) == N && ncol(x) >= 2L) wide <<- wide + 1L
      if (is.list(x)) for (v in x) scan(v)
    }
    scan(unclass(fit))
    testthat::expect_identical(wide, 0L)
    # The row envelope is affine in the batch size (automatic planner contract).
    env <- aug_ns("augmented_if_envelope")
    e1 <- env(fit, 1, seq_along(fit$links))
    e2 <- env(fit, 2, seq_along(fit$links))
    e3 <- env(fit, 3, seq_along(fit$links))
    testthat::expect_equal(e3$output - e2$output, e2$output - e1$output)
    testthat::expect_equal(e3$scratch - e2$scratch, e2$scratch - e1$scratch)
    # Selection rows are evaluated on theta coordinates only (rate rows excluded).
    testthat::expect_true(all(e1$uids > fit$up_map$n_a))
  }
})
